### 💡 Intuition & Approach
The implementation computes **Tokenization** by following direct architectural principles, leveraging vectorized operations to ensure both correctness and optimal runtime efficiency.

### ⚡ Python Reference Implementation
```python
class SimpleTokenizer:
    def __init__(self):
        self.word_to_id = {"<PAD>": 0, "<UNK>": 1, "<BOS>": 2, "<EOS>": 3}
        self.id_to_word = {0: "<PAD>", 1: "<UNK>", 2: "<BOS>", 3: "<EOS>"}
        self.vocab_size = 4
        self.pad_token = "<PAD>"
        self.unk_token = "<UNK>"
        self.bos_token = "<BOS>"
        self.eos_token = "<EOS>"
        self.build_vocab(["hello world", "this is a test", "hello test"])

    def build_vocab(self, texts: list[str]) -> None:
        words = set()
        for text in texts:
            for w in text.lower().split():
                if w not in self.word_to_id:
                    words.add(w)
        for w in sorted(words):
            idx = len(self.word_to_id)
            self.word_to_id[w] = idx
            self.id_to_word[idx] = w
        self.vocab_size = len(self.word_to_id)

    def encode(self, text: str) -> list[int]:
        unk_id = self.word_to_id["<UNK>"]
        return [self.word_to_id.get(w, unk_id) for w in text.lower().split()]

    def decode(self, ids: list[int]) -> str:
        return " ".join([self.id_to_word.get(i, self.unk_token) for i in ids])

_tok = SimpleTokenizer()
def encode(text: str) -> list[int]:
    return _tok.encode(text)

def decode(ids: list[int]) -> str:
    return _tok.decode(ids)
```

### ⏱️ Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N)$ where $N$ represents the primary sequence length or dimension.
- **Space Complexity**: $\mathcal{O}(N)$ auxiliary memory for computing and storing output representations.
